///  How far to highlight a document that is being highlighted in pieces.
class HighlighterSpansRequest {
  HighlighterSpansRequest._(this._bc, this._bcOffset);
  factory HighlighterSpansRequest(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<HighlighterSpansRequest> reader = _HighlighterSpansRequestReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  One past the last line the caller needs, clamped to the document.
  /// 
  ///  The scan always carries on from where the last one stopped rather than
  ///  starting here: a grammar's state runs from line to line, so a prefix is the
  ///  only thing that can be computed, and the line asked for is where the walk
  ///  may stop and not where it begins.
  int get to => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 4, 0);

  @override
  String toString() {
    return 'HighlighterSpansRequest{to: ${to}}';
  }
}

