///  What one forward scan added.
class HighlighterSpansResponse {
  HighlighterSpansResponse._(this._bc, this._bcOffset);
  factory HighlighterSpansResponse(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<HighlighterSpansResponse> reader = _HighlighterSpansResponseReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  One past the last line the caller already had — the watermark this scan
  ///  carried on from. A caller whose own spans do not reach this far has lost
  ///  step with the document and has to start again from nothing.
  int get from => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 4, 0);
  ///  One past the last line this covers: the new watermark, and the length the
  ///  caller's spans now have. Not the line it was asked for — a rule match
  ///  cannot be cut in two, so a scan stops at a line start at or past its
  ///  target, and this is where it did.
  int get to => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 6, 0);
  ///  The spans for `from..to`, in reading order.
  List<HighlightNode>? get nodes => const fb.ListReader<HighlightNode>(HighlightNode.reader).vTableGetNullable(_bc, _bcOffset, 8);

  @override
  String toString() {
    return 'HighlighterSpansResponse{from: ${from}, to: ${to}, nodes: ${nodes}}';
  }
}

class _HighlighterSpansResponseReader extends fb.TableReader<HighlighterSpansResponse> {
  const _HighlighterSpansResponseReader();

  @override
  HighlighterSpansResponse createObject(fb.BufferContext bc, int offset) => 
    HighlighterSpansResponse._(bc, offset);
}

class HighlighterSpansResponseBuilder {
  HighlighterSpansResponseBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(3);
  }

  int addFrom(int? from) {
    fbBuilder.addUint32(0, from);
    return fbBuilder.offset;
  }
  int addTo(int? to) {
    fbBuilder.addUint32(1, to);
    return fbBuilder.offset;
  }
  int addNodesOffset(int? offset) {
    fbBuilder.addOffset(2, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class HighlighterSpansResponseObjectBuilder extends fb.ObjectBuilder {
  final int? _from;
  final int? _to;
  final List<HighlightNodeObjectBuilder>? _nodes;

  HighlighterSpansResponseObjectBuilder({
    int? from,
    int? to,
    List<HighlightNodeObjectBuilder>? nodes,
  })
      : _from = from,
        _to = to,
        _nodes = nodes;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? nodesOffset = _nodes == null ? null
        : fbBuilder.writeList(_nodes!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    fbBuilder.startTable(3);
    fbBuilder.addUint32(0, _from);
    fbBuilder.addUint32(1, _to);
    fbBuilder.addOffset(2, nodesOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
